// Cell records start as [frame start, trimmed content start, trimmed content end].
// Delimiter validation reuses the content-start slot for its alignment kind.
const enum CellSlot {
  ContentStart = 1,
  Alignment = ContentStart,
  ContentEnd = 2,
  Stride = 3,
