function appendTableCell(
  cells: number[],
  source: string,
  start: number,
  contentStart: number,
  contentEnd: number,
): void {
  contentStart = trimLineWhitespaceStart(source, contentStart, contentEnd);
  contentEnd = trimLineWhitespaceEnd(source, contentStart, contentEnd);
  cells.push(start, contentStart, contentEnd);
}

