    let escapeStart = pipe;
    while (escapeStart > 0 && row.charCodeAt(escapeStart - 1) === Character.ReverseSolidus) {
      escapeStart--;
    }
    if ((pipe - escapeStart) % 2 !== 0) {
      continue;
    }
    lastPipe = contentOffset + pipe;
    if (pipe === 0) {
      contentStart++;
      continue;
    }
