      },
    ],
    builds: [
      { kind: "text", token: InlineKind.LiteralText, build: buildLiteralInlineText },
      { kind: "text", token: InlineKind.Escape, build: buildEscapedInlineText },
      { kind: "text", token: InlineKind.Entity, build: buildDecodedInlineText },
