const codeInfoComplex = /[\\& \t]/;

const codeFenceRule = createFenceRule({
  alternateMarker: Character.Tilde,
  forbiddenInfoMarker: Character.GraveAccent,
  marker: Character.GraveAccent,
  minimumLength: 3,
