import { Character } from "../constants/character.ts";
import { type BlockLines, lineIndentOffset, physicalColumnAt, trimLineWhitespaceStart } from "./lines.ts";
import type { BlockKind } from "../constants/block.ts";
import type { BlockTokenStream } from "./tokens.ts";

export interface Fence {
  indent: number;
  length: number;
  marker: number;
  closingPattern: RegExp;
  offset: number;
}

export interface FenceOptions {
  alternateMarker?: number;
  forbiddenInfoMarker: number;
  marker: number;
  minimumLength: number;
}

interface FenceRule extends FenceOptions {
  closingPattern: RegExp;
  alternateClosingPattern?: RegExp;
}

export function createFenceRule(rule: FenceOptions): FenceRule {
  const closingPattern = (marker: number): RegExp => new RegExp(
    `\\u${marker.toString(16).padStart(4, "0")}+[ \t]*`,
    "y",
  );
  return {
    ...rule,
    closingPattern: closingPattern(rule.marker),
    alternateClosingPattern: rule.alternateMarker === void 0 ? void 0 : closingPattern(rule.alternateMarker),
  };
}

export function fenceAt(
  source: string,
  lines: BlockLines,
  index: number,
  rule: FenceRule,
  markerOffset: number,
): Fence | undefined {
  const marker = source.charCodeAt(markerOffset);
  if (marker !== rule.marker && marker !== rule.alternateMarker) {
    return;
  }
  let offset = markerOffset + 1;
  while (source.charCodeAt(offset) === marker) {
    offset++;
  }
  const length = offset - markerOffset;
  if (length < rule.minimumLength) {
    return;
  }
  if (marker === rule.forbiddenInfoMarker) {
    const lineEnd = lines.end(index);
    while (offset < lineEnd) {
      if (source.charCodeAt(offset++) === marker) {
        return;
      }
    }
  }
  return {
    indent: lines.prefixColumns(index) + markerOffset - lines.start(index),
    marker,
    closingPattern: marker === rule.marker ? rule.closingPattern : rule.alternateClosingPattern!,
    length,
    offset: markerOffset,
  };
}

