import { appendFencedToken, closesFence, createFenceRule, fenceAt } from "../../../block/fence.ts";
import { BlockKind } from "../../../constants/block.ts";
import { Character } from "../../../constants/character.ts";
import { semanticText } from "../../utils.ts";
