import type { Math } from "./types.ts";
import { appendFencedToken, closesFence, createFenceRule, fenceAt } from "../../../block/fence.ts";
import { BlockKind } from "../../../constants/block.ts";
import { Character } from "../../../constants/character.ts";
import { semanticText } from "../../utils.ts";
import type { BlockFeature } from "../../../block/profile.ts";

const mathFenceRule = createFenceRule({
  forbiddenInfoMarker: Character.DollarSign,
  marker: Character.DollarSign,
  minimumLength: 2,
});

function createPhysicalMathLiteral(value: string, info: string, firstLine: number, firstColumn: number, firstOffset: number, lastLine: number, lastColumn: number, lastOffset: number): Math {
  const meta = semanticText(info) || null;
  return { type: "math", meta, value, position: {
      start: { line: firstLine, column: firstColumn, offset: firstOffset },
      end: { line: lastLine, column: lastColumn, offset: lastOffset },
    } };
}

export const blockBuilds: BlockFeature["builds"] = [
  {
    token: BlockKind.MathBlock,
    build(tokenStart, context) {
      const tokens = context.structure.tokens;
      const meta = semanticText(tokens.value<string>(tokenStart)!);
      return {
        type: "math",
        meta: meta || null,
        value: tokens.text(context.source, tokenStart),
        position: context.locator.positionAt(tokens.start(tokenStart), tokens.end(tokenStart)),
      };
    },
  },
];

export const blockStarts: BlockFeature["starts"] = [
  {
    codes: [
      Character.DollarSign,
    ],
    interrupt(source, lines, index, contentOffset) {
      return fenceAt(source, lines, index, mathFenceRule, contentOffset) !== void 0;
    },
    start(source, lines, tokens, start, contentOffset, context) {
      const fence = fenceAt(source, lines, start, mathFenceRule, contentOffset);
      if (!fence) {
        return;
      }
      let end = start + 1;
      while (end < lines.length && !closesFence(source, lines, end, fence)) {
        end++;
      }
      const closed = end < lines.length;
      if (end < lines.length) {
        end++;
      }
      const node = appendFencedToken(
        source,
        lines,
        tokens,
        BlockKind.MathBlock,
        start,
        end,
        fence,
        closed,
        false,
        lines === context.directLines ? createPhysicalMathLiteral : void 0,
      );
      if (node) context.directBlocks!.push(node);
      return end;
    },
  },
];

