import { Character } from "../constants/character.ts";
import { BlockLineField, type BlockLines, lineIndentOffset, physicalColumnAt, trimLineWhitespaceStart } from "./lines.ts";
import type { BlockScanContext } from "./scanner.ts";
import type { BlockKind } from "../constants/block.ts";
import type { BlockTokenStream } from "./tokens.ts";

export interface Fence {
  indent: number;
  length: number;
  marker: number;
  closingPattern: RegExp;
  offset: number;
}

export interface FenceOptions {
  alternateMarker?: number;
  forbiddenInfoMarker: number;
  marker: number;
  minimumLength: number;
}

interface FenceRule extends FenceOptions {
  openingPattern: RegExp;
  alternateOpeningPattern?: RegExp;
  closingPattern: RegExp;
  alternateClosingPattern?: RegExp;
}

export function createFenceRule(rule: FenceOptions): FenceRule {
  const openingPattern = (marker: number): RegExp => {
    const escaped = "\\u" + marker.toString(16).padStart(4, "0");
    return new RegExp(escaped + "{" + Math.max(0, rule.minimumLength - 2) + ",}" + (
      marker === rule.forbiddenInfoMarker
        ? "(?!" + escaped + ")(?=[^" + escaped + "\\r\\n]*(?:\\r|\\n|$))"
        : ""
    ), "y");
  };
  const closingPattern = (marker: number): RegExp => new RegExp(
    `\\u${marker.toString(16).padStart(4, "0")}+[ \t]*`,
    "y",
  );
  return {
    ...rule,
    openingPattern: openingPattern(rule.marker),
    alternateOpeningPattern: rule.alternateMarker === void 0 ? void 0 : openingPattern(rule.alternateMarker),
    closingPattern: closingPattern(rule.marker),
    alternateClosingPattern: rule.alternateMarker === void 0 ? void 0 : closingPattern(rule.alternateMarker),
  };
}

export function fenceAt(
  source: string,
  lines: BlockLines,
  index: number,
  rule: FenceRule,
  markerOffset: number,
): Fence | undefined {
  const marker = source.charCodeAt(markerOffset);
  if (marker !== rule.marker && marker !== rule.alternateMarker) {
    return;
  }
  const opening = marker === rule.marker ? rule.openingPattern : rule.alternateOpeningPattern!;
  const headLength = rule.minimumLength > 1 ? 2 : 1;
  if (headLength === 2 && source.charCodeAt(markerOffset + 1) !== marker) {
    return;
  }
  opening.lastIndex = markerOffset + headLength;
  if (!opening.test(source)) {
    return;
  }
  const length = opening.lastIndex - markerOffset;
  return {
    indent: lines.prefixColumns(index) + markerOffset - lines.start(index),
    marker,
    closingPattern: marker === rule.marker ? rule.closingPattern : rule.alternateClosingPattern!,
    length,
    offset: markerOffset,
  };
}

export function closesFence(source: string, lines: BlockLines, index: number, fence: Fence): boolean {
  const lineStart = lines.start(index);
  const lineEnd = lines.end(index);
  if (lineEnd - lineStart < fence.length) {
    return false;
  }
  const first = source.charCodeAt(lineStart);
  if (first !== fence.marker && first !== Character.Space) {
    return false;
  }
  let offset = lineStart;
  if (first !== fence.marker) {
    const contentOffset = lineIndentOffset(source, lines, index);
    if (contentOffset < 0 || source.charCodeAt(contentOffset) !== fence.marker) {
      return false;
    }
    offset = contentOffset;
  }
  // The pattern accepts markers then whitespace; this probe enforces the minimum count.
  const lastRequired = offset + fence.length - 1;
  if (lastRequired >= lineEnd || source.charCodeAt(lastRequired) !== fence.marker) {
    return false;
  }
  const closing = fence.closingPattern;
  closing.lastIndex = offset;
  return closing.test(source) && closing.lastIndex === lineEnd;
}

// Multiline anchors also recognize Unicode separators, which remain literal content.
const fenceSpaceIndent = [
  /^(?<![\u2028\u2029]) /gm,
  /^(?<![\u2028\u2029]) {1,2}/gm,
  /^(?<![\u2028\u2029]) {1,3}/gm,
];
const fenceTabIndent = [
  /^(?<![\u2028\u2029])\t/gm,
  /^(?<![\u2028\u2029]) ?\t/gm,
  /^(?<![\u2028\u2029]) {0,2}\t/gm,
];

/** Publish literal body, info and source position; scan records retain consumed coverage. */
export function appendFencedToken(
  source: string,
  lines: BlockLines,
  tokens: BlockTokenStream,
  kind: BlockKind,
  start: number,
  end: number,
  fence: Fence,
  closed: boolean,
  normalizeEndings: boolean,
  nodeBuilder?: (text: string, info: string, firstLine: number, firstColumn: number, firstOffset: number, lastLine: number, lastColumn: number, lastOffset: number) => object,
): object | undefined {
  const content = lines.physicallyContiguous()
    ? physicalFenceContent(source, lines, start, end - (closed ? 2 : 1), fence.indent, normalizeEndings)
    : logicalFenceContent(source, lines, start, end, closed, fence.indent, normalizeEndings);
  const lineEnd = lines.end(start);
  const infoStart = trimLineWhitespaceStart(source, fence.offset + fence.length, lineEnd);
  const consumedEnd = lines.next(end - 1);
  const spanEnd = closed || consumedEnd < source.length ? lines.end(end - 1) : consumedEnd;
  const info = source.slice(infoStart, lineEnd);
  if (nodeBuilder && lines.physicallyContiguous()) {
    const firstLine = lines.physicalRowIndex(start);
    const last = end - 1;
    const afterEnding = spanEnd > lines.end(last);
    return nodeBuilder(content, info, firstLine, fence.offset - lines.start(start) + 1, fence.offset, firstLine + last - start + (afterEnding ? 1 : 0), afterEnding ? 1 : spanEnd - lines.start(last) + 1, spanEnd);
  }
  tokens.push(
    kind,
    fence.offset,
    spanEnd,
    {
      text: content,
      value: info,
    },
  );
}

/** Exact root-table path: keep fence state in locals and emit no temporary descriptor/token. */
export function parseRootFence(
  source: string,
  lines: BlockLines,
  tokens: BlockTokenStream,
  start: number,
  markerOffset: number,
  rule: FenceRule,
  normalizeEndings: boolean,
  nodeBuilder: (text: string, info: string, firstLine: number, firstColumn: number, firstOffset: number, lastLine: number, lastColumn: number, lastOffset: number) => object,
  context: BlockScanContext,
): number | undefined {
  const marker = source.charCodeAt(markerOffset);
  if (marker !== rule.marker && marker !== rule.alternateMarker) return;
  const headLength = rule.minimumLength > 1 ? 2 : 1;
  if (headLength === 2 && source.charCodeAt(markerOffset + 1) !== marker) return;
  const opening = marker === rule.marker ? rule.openingPattern : rule.alternateOpeningPattern!;
  opening.lastIndex = markerOffset + headLength;
  if (!opening.test(source)) return;
  const length = opening.lastIndex - markerOffset;
  const closing = marker === rule.marker ? rule.closingPattern : rule.alternateClosingPattern!;
  const fields = lines.borrowedFields();
  const count = lines.length;
  const firstStart = fields[start * BlockLineField.Stride | BlockLineField.Start];
  let end = start + 1;
  for (; end < count; end++) {
    const field = end * BlockLineField.Stride;
    let offset = fields[field | BlockLineField.Start];
    const lineEnd = fields[field | BlockLineField.End];
    if (lineEnd - offset < length) continue;
    const first = source.charCodeAt(offset);
    if (first !== marker) {
      if (first !== Character.Space) continue;
      const limit = offset + 3;
      do { offset++; } while (offset < limit && source.charCodeAt(offset) === Character.Space);
      if (source.charCodeAt(offset) !== marker) continue;
    }
    const lastRequired = offset + length - 1;
    if (lastRequired >= lineEnd || source.charCodeAt(lastRequired) !== marker) continue;
    closing.lastIndex = offset;
    if (closing.test(source) && closing.lastIndex === lineEnd) break;
  }
  const closed = end < count;
  if (closed) end++;
  const content = physicalFenceContent(source, lines, start, end - (closed ? 2 : 1), markerOffset - firstStart, normalizeEndings);
  const lineEnd = fields[start * BlockLineField.Stride | BlockLineField.End];
  const info = source.slice(trimLineWhitespaceStart(source, markerOffset + length, lineEnd), lineEnd);
  const last = end - 1;
  const lastStart = fields[last * BlockLineField.Stride | BlockLineField.Start];
  const lastEnd = fields[last * BlockLineField.Stride | BlockLineField.End];
  const consumedEnd = fields[last * BlockLineField.Stride | BlockLineField.Next];
  const spanEnd = closed || consumedEnd < source.length ? lastEnd : consumedEnd;
  const afterEnding = spanEnd > lastEnd;
  context.emitDirectBlock(nodeBuilder(content, info, start + 1, markerOffset - firstStart + 1, markerOffset, end + (afterEnding ? 1 : 0), afterEnding ? 1 : spanEnd - lastStart + 1, spanEnd), tokens);
  return end;
}

function physicalFenceContent(
  source: string,
  lines: BlockLines,
  start: number,
  last: number,
  indent: number,
  normalizeEndings: boolean,
): string {
  const firstOffset = lines.next(start);
  let content = source.slice(firstOffset, last > start ? lines.end(last) : firstOffset);
  if (normalizeEndings) {
    content = lines.normalizeLineEndings(content);
  }
  if (!indent) {
    return content;
  }
  if (content.includes("\t")) {
    content = content.replace(fenceTabIndent[indent - 1], "    ");
  }
  return content.replace(fenceSpaceIndent[indent - 1], "");
}

function logicalFenceContent(
  source: string,
  lines: BlockLines,
  start: number,
  end: number,
  closed: boolean,
  indent: number,
  normalizeEndings: boolean,
): string {
  let last = end - (closed ? 2 : 1);
  // A final empty projected row without an ending contributes no body line.
  if (!closed && last > start && lines.start(last) === lines.next(last) && !lines.prefixColumns(last)) {
    last--;
  }
  const parts: string[] = [];
  for (let index = start + 1; index <= last; index++) {
    let offset = lines.start(index);
    const lineEnd = lines.end(index);
    let columns = lines.prefixColumns(index);
    while (offset < lineEnd && columns < indent) {
      const code = source.charCodeAt(offset);
      if (code === Character.Space) {
        columns++;
      }
      else if (code === Character.CharacterTabulation) {
        columns += 4 - physicalColumnAt(source, offset) % 4;
      }
      else {
        break;
      }
      offset++;
    }
    parts.push(
      " ".repeat(Math.max(0, columns - indent)) + source.slice(offset, lineEnd) + (
        index < last
          ? normalizeEndings
            ? "\n"
            : source.slice(lineEnd, lines.next(index))
          : ""
      ),
    );
  }
  return parts.join("");
}

