        const word1 = words[offset | 1];
        const word2 = words[offset | 2];
        const word3 = words[offset | 3];
        const word4 = words[offset | 4];
        const word5 = words[offset | 5];
        const word6 = words[offset | 6];
        const word7 = words[offset | 7];
