  tokens: BlockTokenStream,
  kind: BlockKind,
  start: number,
  end: number,
  fence: Fence,
  closed: boolean,
  normalizeEndings: boolean,
  nodeBuilder?: (text: string, info: string, firstLine: number, firstColumn: number, firstOffset: number, lastLine: number, lastColumn: number, lastOffset: number) => object,
): object | undefined {
