  indent: number;
  length: number;
  marker: number;
  closingPattern: RegExp;
  offset: number;
}

export interface FenceOptions {
  alternateMarker?: number;
  forbiddenInfoMarker: number;
  marker: number;
  minimumLength: number;
}

interface FenceRule extends FenceOptions {
  closingPattern: RegExp;
  alternateClosingPattern?: RegExp;
}

export function createFenceRule(rule: FenceOptions): FenceRule {
  const closingPattern = (marker: number): RegExp => new RegExp(
    `\\u${marker.toString(16).padStart(4, "0")}+[ \t]*`,
    "y",
  );
  return {
    ...rule,
    closingPattern: closingPattern(rule.marker),
    alternateClosingPattern: rule.alternateMarker === void 0 ? void 0 : closingPattern(rule.alternateMarker),
  };
}

export function fenceAt(
  source: string,
  lines: BlockLines,
  index: number,
  rule: FenceRule,
  markerOffset: number,
): Fence | undefined {
  const marker = source.charCodeAt(markerOffset);
  if (marker !== rule.marker && marker !== rule.alternateMarker) {
    return;
  }
  let offset = markerOffset + 1;
  while (source.charCodeAt(offset) === marker) {
    offset++;
  }
  const length = offset - markerOffset;
  if (length < rule.minimumLength) {
    return;
  }
  if (marker === rule.forbiddenInfoMarker) {
    const lineEnd = lines.end(index);
    while (offset < lineEnd) {
      if (source.charCodeAt(offset++) === marker) {
        return;
      }
    }
  }
  return {
    indent: lines.prefixColumns(index) + markerOffset - lines.start(index),
    marker,
    closingPattern: marker === rule.marker ? rule.closingPattern : rule.alternateClosingPattern!,
    length,
    offset: markerOffset,
  };
}

export function closesFence(source: string, lines: BlockLines, index: number, fence: Fence): boolean {
  return findFenceEnd(source, lines, index, fence, index + 1) === index;
}

export function findFenceEnd(
  source: string,
  lines: BlockLines,
  start: number,
  fence: Fence,
  limit = lines.length,
): number {
  const { marker, length, closingPattern } = fence;
  for (; start < limit; start++) {
    let offset = lines.start(start);
    const first = source.charCodeAt(offset);
    if (first !== marker) {
      if (first !== Character.Space) {
        continue;
      }
      offset = lineIndentOffset(source, lines, start);
      if (offset < 0 || source.charCodeAt(offset) !== marker) {
        continue;
      }
    }
    const lineEnd = lines.end(start);
    const lastRequired = offset + length - 1;
    if (lastRequired >= lineEnd || source.charCodeAt(lastRequired) !== marker) {
      continue;
    }
    closingPattern.lastIndex = offset;
    if (closingPattern.test(source) && closingPattern.lastIndex === lineEnd) {
      return start;
    }
  }
  return limit;
}

// Multiline anchors also recognize Unicode separators, which remain literal content.
