        BlockKind.MathBlock,
        start,
        end,
        fence,
        closed,
        false,
        lines === context.directLines ? createPhysicalMathLiteral : void 0,
      );
      if (node) {
        context.emitDirectBlock(node, tokens);
      }
      return end;
    },
  },
];

