import type { Buffer } from "node:buffer";
import { Character } from "../constants/character.ts";
import type { SourceLocation, SourceLocator, SourcePosition } from "../source-view.ts";

const enum BlockLineField {
  Start,
  End,
  Next,
  State,
  Stride,
}

const enum BlockLineState {
  Lazy = 1,
}

const enum BlockLineCapacity {
  Initial = 4,
  DoublingLimit = 16,
}

export const enum IndentedLine {
  Underindented = -1,
  Blank,
  Appended,
}

interface ScanningResult {
  fields: Int32Array;
  length: number;
  normalized: boolean;
}

// Typical Markdown lines exceed 16 characters; cap the hint at 16,384 lines.
function getLineCapacity(sourceLength: number): number {
  return Math.min((sourceLength + 15) >>> 4, 16384);
}

function growLineFields(fields: Int32Array, fieldLength: number): Int32Array {
  if (fieldLength <= fields.length) {
    return fields;
  }
  let capacity = fields.length / BlockLineField.Stride;
  while (capacity < fieldLength / BlockLineField.Stride) {
    capacity += capacity < BlockLineCapacity.DoublingLimit
      ? Math.max(BlockLineCapacity.Initial, capacity)
      : capacity >>> 1;
  }
  const next = new Int32Array(capacity * BlockLineField.Stride);
  next.set(fields);
  return next;
}

function physicalFenceHeader(
  source: string,
  chars: Uint16Array | undefined,
  words: Uint32Array | undefined,
  start: number,
  end: number,
): number {
  if (start === end) {
    return 0;
  }
  let offset = start;
  let code = chars ? chars[offset] : source.charCodeAt(offset);
  while (code === Character.Space && offset < end && offset - start < 3) {
    offset++;
    code = chars ? chars[offset] : source.charCodeAt(offset);
  }
  if (code !== Character.GraveAccent && code !== Character.Tilde && code !== Character.DollarSign) {
    return 0;
  }
  const minimum = code === Character.DollarSign ? 2 : 3;
  if (offset + minimum > end) {
    return 0;
  }
  for (let at = offset; at < offset + minimum; at++) {
    if ((chars ? chars[at] : source.charCodeAt(at)) !== code) {
      return 0;
    }
  }
  let run = offset + minimum;
  if (chars) {
    if ((run & 1) && run < end && chars[run] === code) {
      run++;
    }
    if (!(run & 1)) {
      const pair = code | code << 16;
      while (run + 1 < end && words![run >>> 1] === pair) {
        run += 2;
      }
      if (run < end && chars[run] === code) {
        run++;
      }
    }
  }
  else {
    while (source.charCodeAt(run) === code) {
      run++;
    }
  }
  const tag = code === Character.GraveAccent ? 1 : code === Character.Tilde ? 2 : 3;
  const length = run - offset;
  return length < 0x08000000 ? length << 4 | tag << 2 | offset - start : -1;
}

class Latin1 {
  static minimum = 2048;
  static scratchBytes: Buffer | undefined;
  static scratchWords: Uint32Array | undefined;
  static scratchChars: Uint16Array | undefined;
  static scratchLimit = 0;
  static allocate = globalThis.Buffer?.allocUnsafeSlow;

  static scan(source: string, fields: Int32Array): ScanningResult {
    const limit = source.length;
    const wordLimit = limit + 15 & ~15;
    if (this.scratchLimit < wordLimit) {
      const bytes = this.allocate(wordLimit * 2);
      this.scratchBytes = bytes;
      this.scratchWords = new Uint32Array(bytes.buffer, bytes.byteOffset, wordLimit >>> 1);
      this.scratchChars = new Uint16Array(bytes.buffer, bytes.byteOffset, wordLimit);
      this.scratchLimit = wordLimit;
    }
