        const mixed5 = (word5 ^ (word5 >>> 1 & 0x7FFF7FFF)) & 0xFFFBFFFB ^ 0x000B000B;
        const mixed6 = (word6 ^ (word6 >>> 1 & 0x7FFF7FFF)) & 0xFFFBFFFB ^ 0x000B000B;
        const mixed7 = (word7 ^ (word7 >>> 1 & 0x7FFF7FFF)) & 0xFFFBFFFB ^ 0x000B000B;
