  let run = offset + minimum;
  if (chars) {
    if ((run & 1) && run < end && chars[run] === code) {
      run++;
    }
    if (!(run & 1)) {
      const pair = code | code << 16;
      while (run + 1 < end && words![run >>> 1] === pair) {
        run += 2;
      }
      if (run < end && chars[run] === code) {
        run++;
      }
    }
